#!/bin/bash

# Reference:
# https://0pointer.de/blog/projects/three-levels-of-off

[ -f "$0" ] || { echo "Cannot run as dot command." >&2; kill -INT $$; }

# Define variables and constants.

# Usage Functions.
usage() {
    cat << EOF
Usage: rcm system stop service

Options:
   --name=Name
        Set the anme of service.
EOF
}

[ -f "${RCM_LIB}/require.sh" ] && source "${RCM_LIB}/require.sh" || { usage >&2; exit 1; }

# Parse arguments. Generated by parse-options.sh.
_new_arguments=()
while [[ $# -gt 0 ]]; do
    case "$1" in
        --help) help=1; shift ;;
        --version) version=1; shift ;;
        --name=*) name="${1#*=}"; shift ;;
        --name) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then name="$2"; shift; fi; shift ;;
        --[^-]*) shift ;;
        *) _new_arguments+=("$1"); shift ;;
    esac
done
set -- "${_new_arguments[@]}"
unset _new_arguments

# Help and Version.
[ -n "$help" ] && { usage; exit 0; }
[ -n "$version" ] && { e $RCM_EXTENSION_VERSION; x; }

# ------------------------------------------------------------------------------

# Title.
title rcm system stop service
____

# Dependency.

# Mapping operand to value of options.
chapter Mapping operand as value of options.
if [ -n "$1" ];then
    code --name=$1
    name="$1"; shift
fi
____

# Require, validate, and populate value.
chapter Variable dump.
if [ -z "$name" ];then
    error "Argument --name is required."; x
fi
code name=$
____

# First, check via System D.
chapter System Daemon
go=
if command -v systemctl >/dev/null 2>&1 && systemctl show --property=Version >/dev/null 2>&1; then
    if systemctl is-active --quiet "${name}.service"; then
        __ "Found $name in systemd and already active."
        go=1
    else
        __ "Service $name already stop."
    fi
fi
____

if [ -n "$go" ];then
    systemctl stop "${name}.service" || x Something error occurred.
    if systemctl is-active --quiet "${name}.service"; then
        error "Service $name is not successfully to stop."
    else
        success "Service $name successfully to stop."
    fi
fi

exit 0

